import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

maxpool2d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void maxpool2d_kernel(
    const float* input,
    float* output,
    int batch_size,
    int channels,
    int height,
    int width,
    int outH,
    int outW,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int total_threads
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_threads) return;

    int out_w = idx % outW;
    int out_h = (idx / outW) % outH;
    int c = (idx / (outH * outW)) % channels;
    int b = idx / (channels * outH * outW);

    int start_h = out_h * stride - padding;
    int start_w = out_w * stride - padding;

    float max_val = -FLT_MAX;

    for(int fh = 0; fh < kernel_size; fh++) {
        for(int fw = 0; fw < kernel_size; fw++) {
            int h = start_h + fh * dilation;
            int w = start_w + fw * dilation;
            if(h >= 0 && h < height && w >= 0 && w < width) {
                float val = input[ ((b * channels + c) * height + h) * width + w ];
                if(val > max_val) {
                    max_val = val;
                }
            }
        }
    }

    output[ ((b * channels + c) * outH + out_h) * outW + out_w ] = max_val;
}

torch::Tensor maxpool2d_cuda(
    torch::Tensor input,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    auto device = input.device();
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");

    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);

    // Calculate output dimensions
    int outH = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int outW = (width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::empty({batch_size, channels, outH, outW}, input.options());

    int total_threads = batch_size * channels * outH * outW;

    int threads = 256;
    int blocks = (total_threads + threads - 1) / threads;

    maxpool2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        outH,
        outW,
        kernel_size,
        stride,
        padding,
        dilation,
        total_threads
    );

    return output;
}
"""

maxpool2d_cpp_source = r"""
torch::Tensor maxpool2d_cuda(torch::Tensor input, int kernel_size, int stride, int padding, int dilation);
"""

maxpool2d = load_inline(
    name="maxpool2d",
    cpp_sources=maxpool2d_cpp_source,
    cuda_sources=maxpool2d_source,
    functions=["maxpool2d_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Custom Model with a fused CUDA 2D MaxPool operator.
    """
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return maxpool2d.maxpool2d_cuda(
            x, self.kernel_size, self.stride, self.padding, self.dilation
        )
